// Französisch: geschütztes Leerzeichen vor ? ! : ; » und nach « (sonst bricht die Zeile davor um)
Object.keys(TXT.fr).forEach(function (k) {
  TXT.fr[k] = TXT.fr[k].replace(/ ([?!:;»])/g, " $1").replace(/« /g, "« ");
});

// Polnisch: 2–4, 22–24 … ("za 3 miesiące") anders als 5–21 ("za 5 miesięcy")
function fewForm(n) { n = Math.abs(n); var a = n % 10, b = n % 100; return a >= 2 && a <= 4 && (b < 12 || b > 14); }
// Einzahl/Mehrzahl: "dl.remindVal.one" bei n = 1, "….few" für die polnischen Zwischenformen
function pluralKey(key, n) {
  var tx = TXT[LANG] || {};
  if (n === 1 && (tx[key + ".one"] || TXT.en[key + ".one"])) return key + ".one";
  if (tx[key + ".few"] && fewForm(n)) return key + ".few";
  return key;
}

// Text in der App-Sprache, fehlende Übersetzungen fallen auf Englisch zurück
function t(key, vars) {
  if (vars && typeof vars.n === "number") key = pluralKey(key, vars.n);
  var s = (TXT[LANG] && TXT[LANG][key]) || TXT.en[key] || TXT.de[key] || key;
  if (vars) s = s.replace(/\{(\w+)\}/g, function (m, k) { return vars[k] != null ? vars[k] : m; });
  return s;
}
// Zitat in den Anführungszeichen der Sprache
function quote(s) { return t("q.open") + s + t("q.close"); }
